namespace AlpineQuestPort {
 internal static class RouteTerrain {
  internal static TerrainProfile Create(Track track){
   if(track.Points.Count<2)throw new ArgumentException("Для профиля нужны две точки маршрута.");
   var vertices=track.Points.ToArray();var cumulative=new double[vertices.Length];for(int i=0;i<vertices.Length;i++){if(!GeoMath.IsValidCoordinate(vertices[i].Lat,vertices[i].Lon))throw new ArgumentException("Некорректная точка маршрута.");if(i>0)cumulative[i]=cumulative[i-1]+GeoMath.DistanceMeters(vertices[i-1],vertices[i]);}
   double length=cumulative.Last();if(length<1)throw new ArgumentException("Маршрут короче одного метра.");int count=Math.Max(2,(int)Math.Min(4096,Math.Ceiling(length/30)));
   var p=new TerrainProfile{Length=length,Points=new GeoPoint[count+1],X=new double[count+1],Heights=Enumerable.Repeat(double.NaN,count+1).ToArray()};int segment=1;
   for(int i=0;i<=count;i++){double distance=length*i/count;p.X[i]=distance;while(segment<vertices.Length-1&&cumulative[segment]<distance)segment++;p.Points[i]=RangeRings.Destination(vertices[segment-1],Math.Max(0,distance-cumulative[segment-1]),TerrainProfile.Bearing(vertices[segment-1],vertices[segment]));}p.Points[0]=vertices[0];p.Points[count]=vertices.Last();return p;
  }
  internal static string Summary(TerrainProfile p){var known=p.Heights.Where(GeoMath.IsFinite).ToArray();string text="Длина: "+(p.Length/1000).ToString("0.00")+" км";if(known.Length==0)return text+" · высоты ещё не загружены";double up=0,down=0;for(int i=1;i<p.Heights.Length;i++)if(GeoMath.IsFinite(p.Heights[i-1])&&GeoMath.IsFinite(p.Heights[i])){double d=p.Heights[i]-p.Heights[i-1];up+=Math.Max(0,d);down+=Math.Max(0,-d);}return text+" · min "+known.Min().ToString("0.0")+" м · max "+known.Max().ToString("0.0")+" м · диапазон "+(known.Max()-known.Min()).ToString("0.0")+" м\r\nНабор ↑ "+up.ToString("0.0")+" м · сброс ↓ "+down.ToString("0.0")+" м"+(GeoMath.IsFinite(p.Heights[0])&&GeoMath.IsFinite(p.Heights.Last())?" · конец − начало "+(p.Heights.Last()-p.Heights[0]).ToString("+0.0;-0.0;0.0")+" м":"")+(known.Length<p.Heights.Length?" · НЕПОЛНЫЕ данные (только известные участки)":"");}
 }
 internal sealed class RoutePlot:Control {
  internal TerrainProfile Profile;ProfileAxes axes;Point? mouse;
  internal bool SummaryStyle;internal bool LiftMode;internal int SelectedIndex=-1;internal double Lift;bool lifting;ProfileAxes dragAxes;
  internal event Action HeightSelectionChanged;
  internal GeoPoint RaisedPoint(){if(Profile==null||SelectedIndex<0||!GeoMath.IsFinite(Profile.Heights[SelectedIndex]))return null;var original=Profile.Points[SelectedIndex];return new GeoPoint(original.Lat,original.Lon){Name="Высота маршрута · "+(Profile.X[SelectedIndex]/1000).ToString("0.000")+" км · +"+Lift.ToString("0.0")+" м",Elevation=Profile.Heights[SelectedIndex]+Lift};}
  internal void SetLift(double value){Lift=Math.Max(0,Math.Min(10000,value));Invalidate();if(HeightSelectionChanged!=null)HeightSelectionChanged();}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(!LiftMode||e.Button!=MouseButtons.Left||axes==null||Profile==null)return;int index=axes.Sample(e.Location,Profile.Points.Length);if(index<0)return;SelectedIndex=index;dragAxes=axes;lifting=true;Capture=true;SetLift(GeoMath.IsFinite(Profile.Heights[index])?axes.HeightAtY(e.Y)-Profile.Heights[index]:0);}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(e.Button==MouseButtons.Left){lifting=false;Capture=false;dragAxes=null;Invalidate();}}

  internal event Action<GeoPoint> Pick,Locate;internal Func<GeoPoint> TemporaryPoint;internal Action RemoveTemporary;
  internal RoutePlot(){DoubleBuffered=true;BackColor=Color.FromArgb(24,28,30);ForeColor=Color.White;Resize+=delegate{Invalidate();};MouseMove+=delegate(object sender,MouseEventArgs e){mouse=e.Location;if(lifting&&SelectedIndex>=0&&GeoMath.IsFinite(Profile.Heights[SelectedIndex]))SetLift(dragAxes.HeightAtY(e.Y)-Profile.Heights[SelectedIndex]);Invalidate();};MouseLeave+=delegate{mouse=null;Invalidate();};MouseClick+=delegate(object sender,MouseEventArgs e){var point=ProfilePointActions.At(Profile,axes,e.Location);if(point==null)return;if(e.Button==MouseButtons.Left){if(!LiftMode&&Pick!=null)Pick(point);}else if(e.Button==MouseButtons.Right)ProfilePointActions.Menu(this,e.Location,point,p=>{if(Pick!=null)Pick(p);},p=>{if(Locate!=null)Locate(p);},TemporaryPoint!=null&&ProfilePointActions.HitTemporary(Profile,axes,e.Location,new[]{TemporaryPoint()}.Where(v=>v!=null))!=null?(Action)(()=>{if(RemoveTemporary!=null)RemoveTemporary();Invalidate();}):null);};}
  void DrawTemporary(Graphics g){if(TemporaryPoint==null)return;var mark=TemporaryPoint();if(mark==null)return;int i=RayProfilePainter.NearestTemporarySample(Profile,mark);if(i<0||!GeoMath.IsFinite(Profile.Heights[i]))return;float x=axes.Plot.Left+(float)(Profile.X[i]/Profile.Length)*axes.Plot.Width,y=axes.Y(Profile.Heights[i]);using(var pen=new Pen(Color.Orange,1){DashStyle=DashStyle.Dot})g.DrawLine(pen,x,axes.Plot.Top,x,axes.Plot.Bottom);g.FillEllipse(Brushes.Orange,x-4,y-4,8,8);}
  void DrawSummary(Graphics g){var p=Profile;axes.Plot=new RectangleF(12,28,Math.Max(20,Width-24),Math.Max(20,Height-48));using(var line=new Pen(Color.FromArgb(57,128,126),2))using(var fill=new SolidBrush(Color.FromArgb(24,57,128,126))){for(int i=1;i<p.X.Length;i++)if(GeoMath.IsFinite(p.Heights[i-1])&&GeoMath.IsFinite(p.Heights[i])){var a=new PointF(axes.Plot.Left+(float)(p.X[i-1]/p.Length)*axes.Plot.Width,axes.Y(p.Heights[i-1]));var b=new PointF(axes.Plot.Left+(float)(p.X[i]/p.Length)*axes.Plot.Width,axes.Y(p.Heights[i]));g.FillPolygon(fill,new[]{a,b,new PointF(b.X,axes.Plot.Bottom),new PointF(a.X,axes.Plot.Bottom)});g.DrawLine(line,a,b);}}
   var valid=Enumerable.Range(0,p.Heights.Length).Where(i=>GeoMath.IsFinite(p.Heights[i])).ToArray();if(valid.Length==0)return;foreach(int index in new[]{valid.OrderBy(i=>p.Heights[i]).First(),valid.OrderByDescending(i=>p.Heights[i]).First()}.Distinct()){float x=axes.Plot.Left+(float)(p.X[index]/p.Length)*axes.Plot.Width,y=axes.Y(p.Heights[index]);g.FillEllipse(Brushes.DarkSlateGray,x-4,y-4,8,8);g.DrawString(p.Heights[index].ToString("0.0")+" м",Font,Brushes.DarkSlateGray,Math.Min(Width-85,Math.Max(8,x+6)),Math.Max(0,y-24));}
  }
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var p=Profile;if(p==null)return;var known=p.Heights.Where(GeoMath.IsFinite).ToArray();if(known.Length==0){e.Graphics.DrawString("Ожидание DEM… Незагруженные высоты не заменяются нулём.",Font,SummaryStyle?Brushes.DarkSlateGray:Brushes.LightGray,20,30);return;}axes=lifting?dragAxes:ProfileAxes.Create(known.Min(),Math.Max(known.Max(),SelectedIndex>=0&&GeoMath.IsFinite(p.Heights[SelectedIndex])?p.Heights[SelectedIndex]+Lift:known.Max()),p.Heights,Width,Height,0,false);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;if(SummaryStyle){DrawSummary(g);DrawTemporary(g);return;}axes.Draw(g,Font);g.DrawString("Рельеф DEM · деления 10 м · щелчок — временная точка · правая кнопка — перейти на карте",Font,Brushes.LightGray,axes.Plot.Left,20);
   using(var pen=new Pen(Color.WhiteSmoke,2))for(int i=1;i<p.X.Length;i++)if(GeoMath.IsFinite(p.Heights[i-1])&&GeoMath.IsFinite(p.Heights[i]))g.DrawLine(pen,axes.Plot.Left+(float)(p.X[i-1]/p.Length)*axes.Plot.Width,axes.Y(p.Heights[i-1]),axes.Plot.Left+(float)(p.X[i]/p.Length)*axes.Plot.Width,axes.Y(p.Heights[i]));
   for(int n=0;n<=4;n++){string label=(p.Length*n/4000).ToString("0.00")+" км";float x=axes.Plot.Left+axes.Plot.Width*n/4;g.DrawString(label,Font,Brushes.LightGray,Math.Min(Width-75,x-20),axes.Plot.Bottom+12);}
   if(SelectedIndex>=0&&GeoMath.IsFinite(p.Heights[SelectedIndex])){float markerX=axes.Plot.Left+(float)(p.X[SelectedIndex]/p.Length)*axes.Plot.Width,markerY=axes.Y(p.Heights[SelectedIndex]+Lift);using(var stem=new Pen(Color.MediumTurquoise,2)){g.DrawLine(stem,markerX,axes.Y(p.Heights[SelectedIndex]),markerX,markerY);}g.FillEllipse(Brushes.MediumTurquoise,markerX-6,markerY-6,12,12);g.DrawString("+"+Lift.ToString("0.0")+" м · "+(p.Heights[SelectedIndex]+Lift).ToString("0.0")+" м",Font,Brushes.MediumTurquoise,Math.Max(axes.Plot.Left,Math.Min(axes.Plot.Right-160,markerX+10)),Math.Max(axes.Plot.Top,markerY-22));}
   DrawTemporary(g);
   if(!mouse.HasValue||!axes.Plot.Contains(mouse.Value))return;int index=axes.Sample(mouse.Value,p.Points.Length);float px=mouse.Value.X,py=mouse.Value.Y;double h=p.Heights[index],cursor=axes.HeightAtY(py);
   using(var pen=new Pen(Color.DeepSkyBlue){DashStyle=DashStyle.Dash}){g.DrawLine(pen,px,axes.Plot.Top,px,axes.Plot.Bottom);if(GeoMath.IsFinite(h)){g.DrawLine(pen,axes.Plot.Left,axes.Y(h),axes.Plot.Right,axes.Y(h));g.FillEllipse(Brushes.DeepSkyBlue,px-4,axes.Y(h)-4,8,8);}}
   using(var pen=new Pen(Color.Gold){DashStyle=DashStyle.Dash})g.DrawLine(pen,axes.Plot.Left,py,axes.Plot.Right,py);
   string detail=axes.Readout(p,index,h)+"\r\nКурсор "+cursor.ToString("0.0")+" м"+(GeoMath.IsFinite(h)?" · к рельефу "+(cursor-h).ToString("+0.0;-0.0;0.0")+" м":"")+(GeoMath.IsFinite(p.Heights[0])?" · от рельефа A "+(cursor-p.Heights[0]).ToString("+0.0;-0.0;0.0")+" м":"");
   using(var background=new SolidBrush(BackColor))g.FillRectangle(background,axes.Plot.Left,40,axes.Plot.Width,Font.Height*2+4);g.DrawString(detail,Font,Brushes.Gold,new RectangleF(axes.Plot.Left+4,40,axes.Plot.Width-8,Font.Height*2+4));
  }
 }
 internal sealed partial class RouteDetailsForm:Form {
  readonly ElevationStore elevation;readonly TerrainProfile profile;readonly RoutePlot plot=new RoutePlot{Dock=DockStyle.Fill};readonly Label stats=new Label{Dock=DockStyle.Top,Height=58},status=new Label{Dock=DockStyle.Bottom,Height=28};readonly Timer timer=new Timer{Interval=100};readonly CheckBox online=new CheckBox{Text="Дозагружать DEM онлайн",AutoSize=true};int cursor;DateTime started;bool complete,stopped,full;FormBorderStyle previousBorder;FormWindowState previousState;
  internal RouteDetailsForm(Track track,string folder,bool network,Action edit,Action<GeoPoint> locate,Action<GeoPoint> add=null,Action<GeoPoint> save=null,Func<GeoPoint> temporary=null,Action removeTemporary=null){Text="Маршрут: "+track.Name;Size=new Size(1150,760);MinimumSize=new Size(700,500);Font=new Font("Segoe UI",10);profile=RouteTerrain.Create(track);elevation=new ElevationStore(Path.Combine(folder,"elevation-cache"));plot.Profile=profile;plot.TemporaryPoint=temporary;plot.RemoveTemporary=removeTemporary;plot.Pick+=add??locate;plot.Locate+=locate;Controls.Add(plot);Controls.Add(stats);Controls.Add(status);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=42};Controls.Add(bar);var editButton=new Button{Text="Редактировать",AutoSize=true};editButton.Click+=delegate{Close();edit();};bar.Controls.Add(editButton);var fullscreen=new Button{Text="Полный экран · F11",AutoSize=true};fullscreen.Click+=delegate{ToggleFull();};bar.Controls.Add(fullscreen);var retry=new Button{Text="Повторить загрузку",AutoSize=true};retry.Click+=delegate{stopped=false;started=DateTime.UtcNow;timer.Start();};bar.Controls.Add(retry);var stop=new Button{Text="Остановить",AutoSize=true};stop.Click+=delegate{stopped=true;timer.Stop();elevation.Tiles.OnlineEnabled=false;status.Text="Загрузка остановлена. Полученные высоты сохранены.";};bar.Controls.Add(stop);online.Checked=network;online.CheckedChanged+=delegate{started=DateTime.UtcNow;stopped=false;timer.Start();};bar.Controls.Add(online);InitializeHeightEditor(save??add??locate);started=DateTime.UtcNow;stats.Text=RouteTerrain.Summary(profile);timer.Tick+=delegate{LoadHeights();};timer.Start();}
  void LoadHeights(){if(stopped||complete)return;try{elevation.Tiles.OnlineEnabled=online.Checked;var watch=System.Diagnostics.Stopwatch.StartNew();bool changed=false;for(int i=0;i<256&&watch.ElapsedMilliseconds<7;i++){int index=cursor++%profile.Points.Length;if(GeoMath.IsFinite(profile.Heights[index]))continue;var h=elevation.At(profile.Points[index],14);if(h.HasValue){profile.Heights[index]=h.Value;changed=true;}}int ready=profile.Heights.Count(GeoMath.IsFinite);complete=ready==profile.Heights.Length;status.Text=(complete?"Высоты готовы":"Высоты: "+ready+" / "+profile.Heights.Length)+" · шаг ≈ "+(profile.Length/(profile.Points.Length-1)).ToString("0")+" м · набор/сброс зависят от точности DEM";if(changed){stats.Text=RouteTerrain.Summary(profile);plot.SetLift(plot.Lift);plot.Invalidate();}if(complete||(DateTime.UtcNow-started).TotalSeconds>180){timer.Stop();elevation.Tiles.OnlineEnabled=false;if(!complete)status.Text="Высоты неполные. Дозагрузите область или нажмите «Повторить загрузку».";}}catch(Exception ex){timer.Stop();Diagnostics.Record("route.dem",ex);status.Text="Ошибка высот: "+ex.Message;}}
  void ToggleFull(){if(!full){previousBorder=FormBorderStyle;previousState=WindowState;WindowState=FormWindowState.Normal;FormBorderStyle=FormBorderStyle.None;WindowState=FormWindowState.Maximized;}else{FormBorderStyle=previousBorder;WindowState=previousState;}full=!full;}
  protected override bool ProcessCmdKey(ref Message msg,Keys key){if(key==Keys.F11||(key==Keys.Escape&&full)){ToggleFull();return true;}return base.ProcessCmdKey(ref msg,key);}
  protected override void Dispose(bool disposing){if(disposing){timer.Dispose();elevation.Dispose();}base.Dispose(disposing);}
 }
 sealed partial class MapCanvas {
  internal event Action<Track> RouteSelected;
  internal bool BuildingRoute {get{return mode==MapMode.Route;}}
  internal int DraftVertices {get{return draft.Count;}}
  internal void NotifyRoute(){var route=Selected as Track;if(route!=null&&RouteSelected!=null)RouteSelected(route);}
 }
 sealed partial class MainForm {
  RouteDetailsForm routeDetails;Timer routeRefreshTimer;
  void OpenRoute(Track route){if(route==null||map.HasDraft)return;try{if(routeDetails!=null&&!routeDetails.IsDisposed)routeDetails.Close();routeDetails=new RouteDetailsForm(route,dataDir,map.Tiles.OnlineEnabled,()=>{if(map.Document.Tracks.Contains(route)){map.Selected=route;map.BeginEdit();map.Focus();}},point=>{map.ShowTemporaryPoint(point,true);map.FindForm().Activate();},map.AddProfilePoint,map.SaveProfilePoint,()=>map.TemporaryPoint,map.ClearTemporaryPoint);routeDetails.Show(this);}catch(Exception ex){Diagnostics.Show(this,"route.open",ex);}}
  void InitializeRoutes(){var bar=new ToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden};ToolStripButton create=new ToolStripButton("Новый маршрут"),finish=new ToolStripButton("Готово · Enter"),undo=new ToolStripButton("Шаг назад"),cancel=new ToolStripButton("Отмена · Esc"),edit=new ToolStripButton("Редактировать маршрут"),info=new ToolStripButton("Профиль и информация");var hint=new ToolStripLabel();bar.Items.AddRange(new ToolStripItem[]{create,finish,undo,cancel,edit,info,hint});Controls.Add(bar);bar.BringToFront();create.Click+=delegate{map.BeginMode(MapMode.Route);map.Focus();};finish.Click+=delegate{map.FinishRoute();};undo.Click+=delegate{map.Undo();};cancel.Click+=delegate{map.CancelDraft();};edit.Click+=delegate{map.BeginEdit();map.Focus();};info.Click+=delegate{OpenRoute(map.Selected as Track);};InitializeObjectCards();map.RouteSelected+=route=>{cardHidden=false;ShowObjectCard(route);};map.PointSelected+=point=>{if(point!=null){cardHidden=false;ShowObjectCard(point);}};var refresh=new Timer{Interval=150};routeRefreshTimer=refresh;refresh.Tick+=delegate{bool active=map.BuildingRoute||map.IsEditing;finish.Visible=undo.Visible=cancel.Visible=active;finish.Enabled=map.IsEditing||map.DraftVertices>=2;create.Enabled=!map.HasDraft;edit.Visible=info.Visible=!active&&map.Selected is Track;hint.Text=map.BuildingRoute?"Щёлкайте точки на карте · "+map.DraftVertices+" точек · соединение напрямую":map.IsEditing?"Тяните вершины · середина ребра добавляет точку · Delete удаляет":"Выберите маршрут на карте или начните новый";};refresh.Start();FormClosed+=delegate{refresh.Dispose();if(routeDetails!=null)routeDetails.Dispose();};}
 }
